ui <- page_sidebar(
  title = "{{project_name}}",
  sidebar = sidebar(
    sliderInput("n", "Points", min = 10, max = 500, value = 100)
  ),
  card(
    card_header("A random sample"),
    plotOutput("plot")
  )
)

server <- function(input, output, session) {
  output$plot <- renderPlot({
    hist(rnorm(input$n), main = NULL, xlab = "Value")
  })
}

shinyApp(ui, server)

